INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Prüfung 1: Planen eines Softwareprodukts > MySQL > DDL (Data Definition Language)
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Wird mit CREATE TABLE in MySQL eine neue Tabelle in der Datenbank erstellt?', 2, '[{"text": "Ja", "correct": true, "because": "CREATE TABLE definiert eine neue Tabelle"}, {"text": "Nein", "correct": false, "because": "Hauptzweck des Befehls"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ALTER TABLE in MySQL verwendet werden, um eine bestehende Tabelle zu löschen?', 2, '[{"text": "Nein", "correct": true, "because": "ALTER TABLE ändert, DROP TABLE löscht"}, {"text": "Ja", "correct": false, "because": "Falscher Befehl für Löschung"}]'),
('00000000-0000-0000-0000-000000000000', 'Löscht DROP TABLE in MySQL eine Tabelle inklusive aller darin enthaltenen Daten?', 2, '[{"text": "Ja", "correct": true, "because": "DROP TABLE entfernt Tabelle und Daten"}, {"text": "Nein", "correct": false, "because": "Komplette Entfernung ist Zweck"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist PRIMARY KEY in MySQL ein Constraint, das die Eindeutigkeit eines Datensatzes sicherstellt?', 2, '[{"text": "Ja", "correct": true, "because": "PRIMARY KEY garantiert Eindeutigkeit"}, {"text": "Nein", "correct": false, "because": "Hauptfunktion des Constraints"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann NOT NULL in MySQL erlauben, dass ein Feld leer bleibt?', 2, '[{"text": "Nein", "correct": true, "because": "NOT NULL verhindert NULL-Werte"}, {"text": "Ja", "correct": false, "because": "Zweck ist Verhinderung von NULL"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher DDL-Befehl wird verwendet, um eine neue Tabelle in MySQL zu erstellen?', 2, '[{"text": "CREATE TABLE", "correct": true, "because": "Definiert eine neue Tabelle"}, {"text": "ALTER TABLE", "correct": false, "because": "Ändert bestehende Tabelle"}, {"text": "DROP TABLE", "correct": false, "because": "Löscht Tabelle"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Befehl in MySQL wird genutzt, um eine Spalte zu einer bestehenden Tabelle hinzuzufügen?', 3, '[{"text": "ALTER TABLE", "correct": true, "because": "ALTER TABLE mit ADD fügt Spalten hinzu"}, {"text": "CREATE TABLE", "correct": false, "because": "Nur für neue Tabellen"}, {"text": "DROP TABLE", "correct": false, "because": "Löscht Tabelle"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Constraint stellt sicher, dass keine doppelten Werte in einer Spalte vorkommen?', 2, '[{"text": "UNIQUE", "correct": true, "because": "UNIQUE erzwingt Eindeutigkeit"}, {"text": "NOT NULL", "correct": false, "because": "Verhindert NULL, nicht Duplikate"}, {"text": "FOREIGN KEY", "correct": false, "because": "Verknüpft Tabellen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher DDL-Befehl entfernt eine Tabelle vollständig aus der Datenbank?', 2, '[{"text": "DROP TABLE", "correct": true, "because": "Löscht Tabelle und Daten"}, {"text": "ALTER TABLE", "correct": false, "because": "Ändert Tabelle"}, {"text": "CREATE TABLE", "correct": false, "because": "Erstellt Tabelle"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Constraint verknüpft eine Spalte mit einer Primärschlüsselspalte in einer anderen Tabelle?', 2, '[{"text": "FOREIGN KEY", "correct": true, "because": "Verknüpft Tabellen über Schlüssel"}, {"text": "PRIMARY KEY", "correct": false, "because": "Definiert Eindeutigkeit"}, {"text": "UNIQUE", "correct": false, "because": "Nur Eindeutigkeit"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche DDL-Befehle gehören zur Datenbankverwaltung in MySQL?', 4, '[{"text": "CREATE TABLE", "correct": true, "because": "Erstellt Tabellen"}, {"text": "ALTER TABLE", "correct": true, "because": "Ändert Tabellen"}, {"text": "DROP TABLE", "correct": true, "because": "Löscht Tabellen"}, {"text": "INSERT", "correct": false, "because": "DML, nicht DDL"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Constraints können in MySQL auf Spalten angewendet werden?', 3, '[{"text": "PRIMARY KEY", "correct": true, "because": "Eindeutigkeit und Identifikation"}, {"text": "FOREIGN KEY", "correct": true, "because": "Verknüpfung mit anderen Tabellen"}, {"text": "NOT NULL", "correct": true, "because": "Verhindert NULL-Werte"}, {"text": "TEXT", "correct": false, "because": "Datentyp, kein Constraint"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Operationen kann ALTER TABLE in MySQL ausführen?', 4, '[{"text": "Spalte hinzufügen", "correct": true, "because": "ADD fügt Spalten hinzu"}, {"text": "Spalte löschen", "correct": true, "because": "DROP entfernt Spalten"}, {"text": "Spalte ändern", "correct": true, "because": "MODIFY ändert Spaltendefinition"}, {"text": "Tabelle löschen", "correct": false, "because": "DROP TABLE erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften charakterisieren einen PRIMARY KEY in MySQL?', 3, '[{"text": "Eindeutigkeit", "correct": true, "because": "Keine Duplikate erlaubt"}, {"text": "Nicht-NULL", "correct": true, "because": "NULL-Werte verboten"}, {"text": "Identifikation", "correct": true, "because": "Eindeutige Datensatz-ID"}, {"text": "Variable Länge", "correct": false, "because": "Eigenschaft von Text"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Auswirkungen hat DROP TABLE in MySQL?', 3, '[{"text": "Tabelle wird entfernt", "correct": true, "because": "Komplette Löschung"}, {"text": "Daten werden gelöscht", "correct": true, "because": "Alle Daten weg"}, {"text": "Constraints werden aufgehoben", "correct": true, "because": "Mit Tabelle gelöscht"}, {"text": "Tabelle wird umbenannt", "correct": false, "because": "RENAME TABLE erforderlich"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) CREATE TABLE erstellt eine neue Tabelle. b) Es kann eine bestehende Tabelle ändern.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Erstellung ja, Änderung nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) ALTER TABLE kann Spalten hinzufügen. b) DROP TABLE löscht nur die Daten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Hinzufügen ja, DROP löscht Tabelle"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) PRIMARY KEY erfordert Eindeutigkeit. b) NOT NULL erlaubt leere Felder.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Eindeutigkeit ja, NULL verboten"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) FOREIGN KEY verknüpft Tabellen. b) UNIQUE erlaubt doppelte Werte.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Verknüpfung ja, Duplikate nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) DROP TABLE entfernt Constraints mit der Tabelle. b) ALTER TABLE kann Tabellen löschen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Constraints ja, Löschen nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

